// Test-only self-signed certificate for CN=reference-log.example.test.
// It contains no production key material and expires in August 2036.
const PFX_BASE64 = ''
const CERT_BASE64 = ''

function pem(label, base64) {
  const lines = base64.match(/.{1,64}/g)
  return `-----BEGIN ${label}-----\n${lines.join('\n')}\n-----END ${label}-----\n`
}

export const REFERENCE_TLS_PFX = Buffer.from(PFX_BASE64, 'base64')
export const REFERENCE_TLS_PASSPHRASE = 'rta-test-only'
export const REFERENCE_TLS_CERTIFICATE = pem('CERTIFICATE', CERT_BASE64)
